#!/usr/bin/env python3
"""Read-only deployment configuration checks. Never prints secret values."""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
from urllib.parse import urlsplit


REQUIRED_SECRETS = {
    "GATEWAY_API_KEY": 32,
    "N8N_ENCRYPTION_KEY": 32,
    "N8N_DB_PASSWORD": 16,
}
OPTIONAL_ENDPOINTS = ("GITEA_BASE_URL", "COMFYUI_BASE_URL", "LLM_BASE_URL", "NOTIFY_WEBHOOK_URL", "GITHUB_API_BASE_URL")


def load_env_file(path: Path) -> dict[str, str]:
    """Parse the simple KEY=VALUE subset generated by this project's .env.example."""
    config: dict[str, str] = {}
    for number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[7:].strip()
        if "=" not in line:
            raise ValueError(f"Invalid .env line {number}: missing '='")
        key, value = line.split("=", 1)
        key = key.strip()
        if not key.isidentifier():
            raise ValueError(f"Invalid variable name on .env line {number}")
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        config[key] = value
    return config


def validate(config: dict[str, str]) -> dict[str, list[str]]:
    errors: list[str] = []
    warnings: list[str] = []
    for name, minimum in REQUIRED_SECRETS.items():
        value = config.get(name, "")
        if not value or value.startswith("REPLACE_WITH"):
            errors.append(f"{name} is missing or contains a sample placeholder")
        elif len(value) < minimum:
            errors.append(f"{name} must contain at least {minimum} characters")

    prefect = config.get("PREFECT_API_URL", "")
    if not prefect:
        errors.append("PREFECT_API_URL is required")
    else:
        parsed = urlsplit(prefect)
        if parsed.scheme not in ("http", "https") or not parsed.netloc or parsed.path.rstrip("/") != "/api":
            errors.append("PREFECT_API_URL must be an HTTP(S) URL ending in /api")
        elif parsed.username or parsed.password:
            errors.append("PREFECT_API_URL must not embed credentials")
        elif parsed.hostname in ("127.0.0.1", "localhost", "::1"):
            warnings.append("PREFECT_API_URL refers to localhost; containers cannot reach the NAS host through their own loopback address")

    for name in OPTIONAL_ENDPOINTS:
        value = config.get(name, "")
        if value:
            parsed = urlsplit(value)
            if parsed.scheme not in ("http", "https") or not parsed.netloc:
                errors.append(f"{name} must be an HTTP(S) URL when configured")
            elif parsed.username or parsed.password:
                errors.append(f"{name} must not embed credentials")

    webhook_secret = config.get("GITEA_WEBHOOK_SECRET", "")
    if webhook_secret and len(webhook_secret) < 32:
        errors.append("GITEA_WEBHOOK_SECRET must contain at least 32 characters when enabled")
    if bool(config.get("LLM_MODEL")) != bool(config.get("LLM_BASE_URL")):
        warnings.append("LLM_MODEL and LLM_BASE_URL should be set together to enable AI summaries")
    if config.get("DOCKER_SOCKET"):
        warnings.append("DOCKER_SOCKET is enabled; Docker socket access is host-privileged, even when mounted read-only")

    editor_url = config.get("N8N_EDITOR_BASE_URL", "http://localhost:5678")
    if editor_url.startswith("https://") and config.get("N8N_SECURE_COOKIE", "false").lower() != "true":
        warnings.append("N8N_SECURE_COOKIE should be true when n8n is served over HTTPS")
    return {"errors": errors, "warnings": warnings}


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate AI Automation Hub deployment configuration without starting services")
    parser.add_argument("--env-file", type=Path, default=Path(".env"))
    parser.add_argument("--json", action="store_true", help="Machine-readable output; never includes secret values")
    args = parser.parse_args()
    if not args.env_file.is_file():
        result = {"errors": [f"Config file not found: {args.env_file}"], "warnings": []}
    else:
        try:
            result = validate(load_env_file(args.env_file))
        except (OSError, UnicodeError, ValueError) as exc:
            result = {"errors": [str(exc)], "warnings": []}
    if args.json:
        print(json.dumps(result, ensure_ascii=False))
    else:
        for message in result["errors"]:
            print(f"ERROR: {message}")
        for message in result["warnings"]:
            print(f"WARN: {message}")
        print("PASS: configuration structure validated" if not result["errors"] else "FAIL: correct the errors before deploying")
    return 1 if result["errors"] else 0


if __name__ == "__main__":
    raise SystemExit(main())
